import{_ as a,o as t,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Why Choose Bagisto?","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/why-choose-bagisto.md","filePath":"getting-started/why-choose-bagisto.md","lastUpdated":1789464754000}'),s={name:"getting-started/why-choose-bagisto.md"};function i(n,e,l,h,c,d){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="why-choose-bagisto" tabindex="-1">Why Choose Bagisto? <a class="header-anchor" href="#why-choose-bagisto" aria-label="Permalink to &quot;Why Choose Bagisto?&quot;">​</a></h1><p><a href="https://bagisto.com/" target="_blank" rel="noreferrer">Bagisto</a> is an open-source e-commerce platform, released under the MIT licence and built as a Laravel application. You install the whole application, then extend it with your own Laravel packages and themes, the same way its own features are built.</p><h2 id="a-stack-you-already-know" tabindex="-1">A Stack You Already Know <a class="header-anchor" href="#a-stack-you-already-know" aria-label="Permalink to &quot;A Stack You Already Know&quot;">​</a></h2><ul><li>Laravel 13 on PHP 8.4, with Vue.js 3, Tailwind CSS 4 and Vite for the admin and the storefront.</li><li>MySQL 8.0, MariaDB 10.11 or PostgreSQL 16.</li><li>Every feature is one of the 42 packages under <code>packages/Webkul/</code>, so the code you extend has the same shape as the code you write. See <a href="./../architecture/overview.html">Architecture Overview</a>.</li></ul><h2 id="commerce-features-in-the-core" tabindex="-1">Commerce Features in the Core <a class="header-anchor" href="#commerce-features-in-the-core" aria-label="Permalink to &quot;Commerce Features in the Core&quot;">​</a></h2><ul><li><strong>Catalog:</strong> simple, configurable, grouped, bundle, downloadable, virtual and booking products; attribute families; a category tree; catalog price rules.</li><li><strong>Selling:</strong> multiple channels, locales and currencies; cart rules and coupons; orders, invoices, shipments and refunds; tax categories and rates.</li><li><strong>Payments and shipping:</strong> cash on delivery, money transfer, PayPal, Stripe, Razorpay, PayU, PayGlocal and PhonePe; flat rate and free shipping, plus any carrier you add.</li><li><strong>Customers:</strong> accounts, groups, wishlists, product comparison, reviews, social login, GDPR data requests, returns (RMA) and EU withdrawal requests.</li><li><strong>Search and SEO:</strong> database or Elasticsearch search, search terms and synonyms, URL rewrites, meta fields, XML sitemaps and a <code>robots.txt</code> per channel.</li><li><strong>Operations:</strong> a full page cache, data import, Amazon S3 and Cloudflare R2 storage, and production Docker images.</li></ul><p>The admin and the storefront are translated into 22 locales.</p><h2 id="generative-ai-and-ai-agent-tools" tabindex="-1">Generative AI and AI Agent Tools <a class="header-anchor" href="#generative-ai-and-ai-agent-tools" aria-label="Permalink to &quot;Generative AI and AI Agent Tools&quot;">​</a></h2><ul><li><a href="./../ai/magic-ai.html">Generative AI (Magic AI)</a> writes product content, generates images, translates reviews, powers image search and writes personalized checkout messages. It works with OpenAI, Anthropic, Gemini, Groq, Mistral, DeepSeek, xAI or a self-hosted Ollama model.</li><li><a href="./../ai/webmcp.html">WebMCP</a> declares storefront actions as tools that a browser AI agent can call for the shopper: open a product, add it to the wishlist, or open the wishlist, the cart or the checkout.</li><li><a href="./../ai/introduction.html">Agent skills and llms.txt</a> teach AI coding agents Bagisto&#39;s conventions.</li></ul><h2 id="built-to-be-extended" tabindex="-1">Built to Be Extended <a class="header-anchor" href="#built-to-be-extended" aria-label="Permalink to &quot;Built to Be Extended&quot;">​</a></h2><ul><li>Add features as packages, change the storefront with themes, and react to core behaviour through events, without editing core files.</li><li>REST and GraphQL APIs come from the separate <code>bagisto/bagisto-api</code> package; see <a href="./../api/introduction.html">REST and GraphQL APIs</a>, and the endpoint reference at <a href="https://api-docs.bagisto.com/" target="_blank" rel="noreferrer">api-docs.bagisto.com</a>.</li><li><a href="https://visual.bagistoplus.com/" target="_blank" rel="noreferrer">Bagisto Visual</a> is a community-built visual theme editor for Bagisto.</li></ul><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p><a href="./before-you-start.html">Before You Start</a> lists what you need on your machine.</p>',13)]))}const p=a(s,[["render",i]]);export{g as __pageData,p as default};
